// void startBatch();
startBatch() {
  if (this.mBatchCount++ == 0) {
    this.mObservers.notify("onStartBatch", [this]);
  }
}

// void endBatch();
endBatch() {
  if (this.mBatchCount > 0) {
    if (--this.mBatchCount == 0) {
      this.mObservers.notify("onEndBatch", [this]);
    }
  } else {
    lazy.log.warn("Unexpected endBatch");
  }
